insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 3, 1, '{"place":"Somewhere warm","narrated":false,"tone":"wry","cupNight":false,"opener":"Somewhere warm. I''d settle for a warm supper. Eat.","forkA":"They need her at home.","forkB":"Home is only the first stop.","callback":"Corin was held a morning''s walk from his own mill. Wren was told she was going home first.","nudge":"{friend:Intellect}, they took Wren back to where she was born. Why home, of all places?","riddle":{"q":"What has to be broken before you can use it?","a":"an egg","quip":"Ashcombe''s hens have views.","accept":["an egg","egg"],"maxTries":3},"leads":[{"id":"3-1-1","place":"Corin, on the walk down","actions":[{"attr":"Charm","verb":"walk beside him and let him talk"},{"attr":"Aim","verb":"look him over in the morning light"}],"clueTitle":"The grey wool","clueText":"Corin has a child''s woollen mitten tucked in his belt that is not his. The wool is rough and grey, and it smells of sheep.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"3-1-2","place":"where the cart stood, below the shaft","actions":[{"attr":"Craft","verb":"read what the cart left in the grass"},{"attr":"Intellect","verb":"work out what they loaded"}],"clueTitle":"The full cask","clueText":"Where the cart stood, a cask has pressed a deep ring into the mud. The grass round it is soaked where they topped it up from the stream, right to the brim.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."},{"id":"3-1-3","place":"the shoulder of the hill he ran over","actions":[{"attr":"Agility","verb":"go up the shoulder after him"},{"attr":"Aim","verb":"follow his line from the shaft mouth"}],"clueTitle":"Facing west","clueText":"At the top of the shoulder the ground is scuffed where he stood a while, facing west. Then his prints go on, the same way the cart went.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"Then they stopped being ours.\"* Whose were they, and what took them?","weekQuestion":"What do they need Wren for?","pull":"They are not hiding her. They told her she was going home.\n\n**Why would anyone take a stolen child back to where she was born? Ashcombe: a long day west.**"}'::jsonb),
('dark-moon', 1, 3, 2, '{"place":"Ashcombe","narrated":false,"tone":"quiet","cupNight":false,"opener":"Eat first. Then think. It goes better in that order.","forkA":"The manners were real.","forkB":"The manners are the trick.","callback":"Tamsin and Corin each came home with one cut palm, bound clean. Wren''s taker said they''d only need her the once.","nudge":"{friend:Charm}, why would men taking a child bother with good manners?","riddle":{"q":"What has an eye but cannot see?","a":"a needle","quip":"Sharp little thing. Sharper than a polite man.","accept":["a needle","needle"],"maxTries":3},"leads":[{"id":"3-2-1","place":"the well, and the board of chips","actions":[{"attr":"Charm","verb":"crouch by the board and wait"},{"attr":"Aim","verb":"watch the well from across the street"}],"clueTitle":"The boy at the well","clueText":"At the well a boy holds his chip out low and quick, then shoves it back into his shirt before you have looked at it properly.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"3-2-2","place":"the empty cart at the foot of the black road","actions":[{"attr":"Craft","verb":"climb up and look over the boards"},{"attr":"Intellect","verb":"go over the cart end to end"}],"clueTitle":"The made bed","clueText":"In the bed of the empty cart a sheepskin is spread over the boards, and a blanket is folded at one end like a pillow.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"3-2-3","place":"the street, where every door shut","actions":[{"attr":"Aim","verb":"walk the street with your eyes on the ground"},{"attr":"Craft","verb":"pick out what is caught between the stones"}],"clueTitle":"Sacking on the stones","clueText":"Caught between the stones down the middle of the street are scraps of sacking. It is the kind men tie over hooves to quiet them on a night road.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"Remember that, when you hear where else we stood.\"* Where else might they have stood?","weekQuestion":"What do they need Wren for?","pull":"**What does anyone need a child for, once? The Blackglass: half a day up the black road, the place Meira marked.**"}'::jsonb),
('dark-moon', 1, 3, 3, '{"place":"The Blackglass","narrated":false,"tone":"wry","cupNight":false,"opener":"Mind your hands on that glass, all of you.","forkA":"The children were chosen for their place.","forkB":"The places were chosen for the children.","callback":"At the Widow''s Tooth a man lay in the bracken watching the rock. Here the riders went past this one without slowing.","nudge":"{friend:Intellect}, why would a scholar write down a number she doubted?","riddle":{"q":"Black when you buy it, red when you burn it, grey when you throw it away. What is it?","a":"coal","quip":"Charcoal''s cheaper than glass. Kinder to knees.","accept":["coal"],"maxTries":3},"leads":[{"id":"3-3-1","place":"where the shepherds'' path meets the glass","actions":[{"attr":"Intellect","verb":"look at where the path gives out"},{"attr":"Agility","verb":"walk the edge of the glass"}],"clueTitle":"The row of stones","clueText":"Where the shepherds'' path meets the glass, a row of old stones lies across it, sunk deep in the turf. The path stops dead at the row.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"3-3-2","place":"the housing beside the mark","actions":[{"attr":"Craft","verb":"run a finger round its carving"},{"attr":"Intellect","verb":"look it over before you step away"}],"clueTitle":"Only your hand","clueText":"The glass round the housing is dull with fine dust. The only marks in it are the ones your own hand just made.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"3-3-3","place":"the far edge, where the glass is cracked","actions":[{"attr":"Aim","verb":"look back the way you came"},{"attr":"Might","verb":"climb onto the highest lip of glass"}],"clueTitle":"The view down","clueText":"From the far edge you can see all the way down the black road to Ashcombe''s roofs, and the well in the middle of them.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"He only never told us the price.\"* The price of what?","weekQuestion":"What do they need Wren for?","pull":"**They rode straight past the one thing Meira marked. So what are they riding to? On, into the black ridges.**"}'::jsonb),
('dark-moon', 1, 3, 4, '{"place":"The black ridges","narrated":false,"tone":"wry","cupNight":true,"opener":"She''s leaving chips on the trail. Clever girl.","forkA":"The chips are for us.","forkB":"The chips are for herself.","callback":"Tamsin wasn''t asleep; she was counting. Wren is dropping her chips, one by one, on their trail.","nudge":"{friend:Agility}, you followed Wren''s chips up the ridges. Left for us, or for herself?","riddle":{"q":"What follows you all day and vanishes at dark?","a":"your shadow","quip":"Long ones on a ridge at dusk.","accept":["shadow","your shadow"],"maxTries":3},"leads":[{"id":"3-4-1","place":"the rises along the riders'' trail","actions":[{"attr":"Aim","verb":"look back down the trail from the last rise"},{"attr":"Agility","verb":"run the trail back to the first chip"}],"clueTitle":"On the bare rock","clueText":"Each chip lay on bare rock at the top of a rise, never down in the ash where it would sink. Coming up behind, you see each one glint before you reach it.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"3-4-2","place":"the bone-white trees along the trail","actions":[{"attr":"Intellect","verb":"set each chip beside what stood near it"},{"attr":"Aim","verb":"look round from where each one lay"}],"clueTitle":"A tree at each","clueText":"Each chip lay a few paces from a dead tree, the tallest one in sight. Stand at one tree, and you can see the next.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"3-4-3","place":"the three chips in your hand","actions":[{"attr":"Craft","verb":"turn each one over in the light"},{"attr":"Intellect","verb":"lay them out side by side"}],"clueTitle":"Scratched on the back","clueText":"Turn the chips over. One has a single short scratch on its back, one has two, and one has three.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"We locked with what we are.\"* What are they?","weekQuestion":"What do they need Wren for?","pull":"**She is alive, and she is thinking. The hut, at first light.**"}'::jsonb),
('dark-moon', 1, 3, 5, '{"place":"The shepherd''s hut","narrated":false,"tone":"wry","cupNight":false,"opener":"That was an empty hut. Come nearer the fire.","forkA":"They left her bed as a message.","forkB":"They left it in a hurry.","callback":"At the mine someone took the time to bind Tamsin''s hand in clean linen. Here someone folded one blanket with care, and threw the other down.","nudge":"{friend:Craft}, what tool cuts letters like that into wood?","riddle":{"q":"What goes through a door but never goes in or out?","a":"a keyhole","quip":"Doors keep secrets better than people.","accept":["a keyhole","keyhole"],"maxTries":3},"leads":[{"id":"3-5-1","place":"low on the doorframe","actions":[{"attr":"Craft","verb":"run a thumbnail along the letters"},{"attr":"Intellect","verb":"look at how each letter was made"}],"clueTitle":"Cut twice","clueText":"Each stroke of the name has been cut twice, the second pass deeper than the first.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"3-5-2","place":"the spring below the hut","actions":[{"attr":"Agility","verb":"get down to the water fast"},{"attr":"Aim","verb":"look over the ground by the spring"}],"clueTitle":"The dropped skin","clueText":"By the spring a water skin lies in the grass, half full. Its stopper is a pace away.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."},{"id":"3-5-3","place":"the wall beside the pallet","actions":[{"attr":"Charm","verb":"sit on the pallet and look round"},{"attr":"Intellect","verb":"look at what is kept by the bed"}],"clueTitle":"The gap in the row","clueText":"Along the wall by the pallet, small things are set out in a row: a twist of grey wool, a white pebble, a hen''s feather. At one end there is a gap, and the dust there is clean.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"That is why kingdoms fear them.\"* Why would a kingdom fear a family?","weekQuestion":"What do they need Wren for?","pull":"**A step, now, and no more. If they could see you, can you see them? The cairn on the highest ridge, before the light goes.**"}'::jsonb),
('dark-moon', 1, 3, 6, '{"place":"The cairn","narrated":false,"tone":"wry","cupNight":false,"opener":"Fire''s built up. Sit by it before you decide anything.","forkA":"We go in now.","forkB":"We watch the lamp first.","callback":"Corin said Wren''s home was always warm. Tonight the map ends at a hill that breathes warm air.","nudge":"{friend:Aim}, a lamp went into the hill ahead of us. Whose was it?","riddle":{"q":"What can you keep only after you''ve given it?","a":"your word","quip":"Mind who hears yours.","accept":["word","your word"],"maxTries":3},"leads":[{"id":"3-6-1","place":"the foot of the round hill","actions":[{"attr":"Aim","verb":"look down at the foot of the hill"},{"attr":"Intellect","verb":"go over every shape below the crown"}],"clueTitle":"No horses","clueText":"Not one horse is tethered at the foot of the Kiln.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"3-6-2","place":"the crack across its crown","actions":[{"attr":"Aim","verb":"watch the crown after the lamp goes in"},{"attr":"Intellect","verb":"watch the air over the crack"}],"clueTitle":"Smoke from the crack","clueText":"Soon after the lamp goes in, thin pale smoke starts to rise from the crack. By daylight there was only shimmering air.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"3-6-3","place":"the knife-edge below the cairn","actions":[{"attr":"Agility","verb":"go a little way back along the edge"},{"attr":"Might","verb":"test the stones of the face"}],"clueTitle":"No way down in the dark","clueText":"Now the light has gone, the knife-edge below the cairn is a black line with nothing either side. The face beside it drops straight to loose scree.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"We never dug him a grave.\"* Why not?","weekQuestion":"What do they need Wren for?","pull":"**Whatever happens under that hill has started. Into the Kiln, tonight.**"}'::jsonb)
